-- 回退 2026-10-27-reference-data-catalog.sql（client-master，DML）。只在 client-master 镜像回退到不识别 REF_ 目录码的版本时同时执行。
-- 内容：恢复 48 行 t_catalog_item（与旧 client-master-initial-data.sql 逐行相同）；catalog_code REF_CURRENCY → CURRENCY、
--       REF_COUNTRY_SUBDIVISION → STATE_OR_PROVINCE；t_party_address 中 ^(AE|EG)-[A-Z0-9]+$ 改回下划线格式。
-- 注意：回退后新提交的 ISO 编码也会一并改回下划线格式（旧镜像只认识下划线目录码）；SA 行政区在旧目录中不存在，不处理。
-- 幂等：目录项按主键 INSERT IGNORE，其余为条件更新；重复执行为空操作。
SET NAMES utf8mb4;
SET time_zone = '+00:00';

SELECT 'before' AS `phase`,
  (SELECT COUNT(*) FROM `t_catalog_item` WHERE `catalog_code` IN ('INDUSTRY', 'CURRENCY', 'STATE_OR_PROVINCE')) AS `catalog_items`,
  (SELECT COUNT(*) FROM `t_onboarding_schema_field` WHERE `catalog_code` = 'REF_CURRENCY') AS `ref_currency_schema_fields`,
  (SELECT COUNT(*) FROM `t_address_format_component` WHERE `catalog_code` = 'REF_COUNTRY_SUBDIVISION') AS `ref_subdivision_components`,
  (SELECT COUNT(*) FROM `t_party_address` WHERE REGEXP_LIKE(`state_or_province`, '^(AE|EG)-[A-Z0-9]+$', 'c')) AS `iso_addresses`;

START TRANSACTION;


UPDATE `t_onboarding_schema_field` SET `catalog_code` = 'CURRENCY', `update_time` = UTC_TIMESTAMP(6)
WHERE `catalog_code` = 'REF_CURRENCY';

UPDATE `t_address_format_component` SET `catalog_code` = 'STATE_OR_PROVINCE', `update_time` = UTC_TIMESTAMP(6)
WHERE `catalog_code` = 'REF_COUNTRY_SUBDIVISION';

UPDATE `t_party_address`
SET `state_or_province` = CONCAT(LEFT(`state_or_province`, 2), '_', SUBSTRING(`state_or_province`, 4)), `update_time` = UTC_TIMESTAMP(6)
WHERE REGEXP_LIKE(`state_or_province`, '^(AE|EG)-[A-Z0-9]+$', 'c');

COMMIT;

SELECT 'after' AS `phase`,
  (SELECT COUNT(*) FROM `t_catalog_item` WHERE `catalog_code` IN ('INDUSTRY', 'CURRENCY', 'STATE_OR_PROVINCE')) AS `catalog_items`,
  (SELECT COUNT(*) FROM `t_onboarding_schema_field` WHERE `catalog_code` = 'CURRENCY') AS `currency_schema_fields`,
  (SELECT COUNT(*) FROM `t_address_format_component` WHERE `catalog_code` = 'STATE_OR_PROVINCE') AS `subdivision_components`,
  (SELECT COUNT(*) FROM `t_party_address` WHERE REGEXP_LIKE(`state_or_province`, '^(AE|EG)_[A-Z0-9]+$', 'c')) AS `underscore_addresses`;
